with base as (select *, initcap(trim(channel)) as channel_title, datediff(ends_on, starts_on) as days_starts_on_to_ends_on, coalesce(channel, 'NONE') as channel_clean from promotions where starts_on between '2024-08-01' and '2024-11-01'), scored as (select *, sum(days_starts_on_to_ends_on) over w_ordered as running_days_starts_on_to_ends_on, percent_rank() over w_hist as discount_pct_percent_rank, lag(discount_pct, 1) over w_ordered_2 as prev_discount_pct from base window w_ordered as (order by days_starts_on_to_ends_on, id rows between unbounded preceding and current row), w_hist as (order by discount_pct), w_ordered_2 as (partition by promo_code, channel order by discount_pct, id)), deduped as (select *, row_number() over (partition by promo_code order by prev_discount_pct, id) as dedup_rank from scored qualify dedup_rank = 1), attributed as (select e.*, pr.id as promo_id, pr.promo_code as promotion_promo_code, pr.discount_pct as promotion_discount_pct from deduped e left join promotions pr on e.channel = pr.channel and e.starts_on between pr.starts_on and pr.ends_on), latest as (select *, rank() over (partition by promotion_promo_code, channel order by discount_pct desc) as dedup_rank_2 from attributed qualify dedup_rank_2 = 1), kept_keys as (select id, channel from latest intersect all select id, channel from promotions where month(ends_on) in (1, 9, 11)), verified as (select s.* from latest s inner join kept_keys k on s.id = k.id and s.channel = k.channel), scored_promotions as (select *, percent_rank() over (order by discount_pct_percent_rank nulls first) as discount_pct_percent_rank_percent_rank, round(promotion_discount_pct / sum(promotion_discount_pct) over (partition by promo_code), 4) as promotion_discount_pct_share, percent_rank() over w_part as prev_discount_pct_percent_rank, stddev_samp(days_starts_on_to_ends_on) over (partition by channel) as channel_stddev_samp_days_starts_on_to_ends_on from verified window w_part as (partition by channel order by prev_discount_pct)) select * from (select promo_code, promotion_promo_code, channel, days_starts_on_to_ends_on from scored_promotions) src pivot (sum(days_starts_on_to_ends_on) as value_sum, count(1) as cnt for channel in ('mobile' as mobile, 'partner' as partner))
